import { Component, Output } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { CommonModule } from '@angular/common';
import { MatDialogRef } from '@angular/material/dialog';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'individual-popup',
  standalone: true,
  imports: [CommonModule, ButtonComponent, MatCheckboxModule, FormsModule],
  templateUrl: './individual-popup.component.html',
  styleUrl: './individual-popup.component.scss'
})
export class IndividualPopupComponent {
  // @Output() OnPopupEvent: any;
  isIndex: boolean = false;
  bShowAgain: boolean = false;
  title: string = 'Exit Evidence';
  subTitle: string = 'You will close all currently opened documents.';
  constructor(private MatDialogRef: MatDialogRef<IndividualPopupComponent>, private store: SecureStorageService) { }

  onClose(flag) {
    this.MatDialogRef.close(flag);
    // this.OnPopupEvent.emit({ type: 'CLOSE', data: flag });
    this.store.setStorage('bShowAgainExitEvidence', this.bShowAgain ? 'Y' : 'N');
  }

  close() {
    this.MatDialogRef.close();
  }

  onChange(event: any) {
    this.bShowAgain = event.checked;
    this.store.setStorage('bShowAgainExitEvidence', this.bShowAgain ? 'Y' : 'N');
  }

  ngOnInit() {

    this.bShowAgain = this.store.getStorage('bShowAgainExitEvidence') == 'Y';
  
  }

}
